  /* ══ 12. Q&A 쌍 — 정규식이 놓친 문장을 dice/키워드로 잡는 백업 ══ */
  function qm(match, c, n, d) {
    for (var i = 0; i < P.length; i++) {
      if (P[i].q !== match) continue;
      if (c) P[i].clean = [].concat(P[i].clean, c);
      if (n) P[i].normal = [].concat(P[i].normal, n);
      if (d) P[i].dorat = [].concat(P[i].dorat, d);
      return;
    }
  }

